@startuml

class Employee {
  + id : int
  + name : string
  + address : string
}

class AssemblyService {
  + kms : int
  + workHours : float
  + admissionDate : date
  + finishDate : date
}

class PartAccessory {
  + category : string
  + serialNumber : string
  + price : double
}

class Car {
  + licensePlate : string
  + make : string
  + model : string
  + color : string
}

class Owner {
  + id : int
  + name : string
  + address : string
  + phone : string
}

class CarModelFit {
}

Employee "1" -- "*" AssemblyService : responsibleFor
AssemblyService "*" -- "1" Car : executedIn
AssemblyService "*" -- "*" PartAccessory : fits
Car "1" -- "*" AssemblyService : undergoes
Car "*" -- "1" Owner : ownedBy
PartAccessory "*" -- "*" CarModelFit : fits
CarModelFit "*" -- "1" Car : matches

@enduml

